begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table conversations_fixture(id uuid,message uuid,reply uuid);grant select,insert,update on conversations_fixture to cuevo_api;
-- This rollback fixture establishes its own reviewed disabled state without assuming previous browser policy.
insert into app.parent_conversation_policies(school_id,version,enabled,reason,approved_by)select '10000000-0000-4000-8000-000000000001',coalesce(max(version),0)+1,false,'Rollback-only synthetic conversation deny fixture.','20000000-0000-4000-8000-000000000001'from app.parent_conversation_policies where school_id='10000000-0000-4000-8000-000000000001';
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.parent_conversation_list('choices',null,'{"limit":100}')$$,'42501',null,'reviewed disabled school policy blocks parent conversation choices');
select throws_ok($$select internal.parent_conversation_command('create',null,'{"learnerId":"20000000-0000-4000-8000-000000000012","parentId":"20000000-0000-4000-8000-000000000072","teacherId":"20000000-0000-4000-8000-000000000004","classId":"30000000-0000-4000-8000-000000000001","subjectId":"43000000-0000-4000-8000-000000000001","title":"Explain checking","body":"Please explain the next step"}','conversation-disabled',repeat('a',64),'conversation-test')$$,'42501',null,'disabled conversation policy blocks parent creation');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select internal.parent_conversation_command('policy',null,jsonb_build_object('enabled',true,'expectedVersion',(internal.parent_conversation_list('policy',null,'{"limit":25}')->>'version')::integer,'reason','School approves controlled parent teacher text','confirmApproval',true),'conversation-policy',repeat('b',64),'conversation-test')is not null as policy;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(jsonb_array_length(internal.parent_conversation_list('choices',null,'{"limit":100}')->'items')>0,'parent choices resolve current exact child teacher class source');
select ok(not exists(select 1 from jsonb_array_elements(internal.parent_conversation_list('choices',null,'{"limit":100}')->'items')choice where choice->>'parentId'<>'20000000-0000-4000-8000-000000000072'),'choices do not widen parent roster');
insert into conversations_fixture(id)values((internal.parent_conversation_command('create',null,'{"learnerId":"20000000-0000-4000-8000-000000000012","parentId":"20000000-0000-4000-8000-000000000072","teacherId":"20000000-0000-4000-8000-000000000004","classId":"30000000-0000-4000-8000-000000000001","subjectId":"43000000-0000-4000-8000-000000000001","title":"Explain checking","body":"Please explain the next step"}','conversation-create',repeat('c',64),'conversation-test')->>'id')::uuid);
update conversations_fixture set message=(internal.parent_conversation_list('messages',id,'{"limit":100}')->'items'->0->>'id')::uuid;
select is(internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')->'items'->0->>'delivery','DELIVERED_IN_APP','delivered state represents committed in-app availability');
select throws_ok($$select internal.parent_conversation_command('read',(select message from conversations_fixture),'{}','conversation-self-read',repeat('d',64),'conversation-test')$$,'22023',null,'sender cannot fabricate recipient read');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')->'items'),0,'administrator raw message view excludes unreported content');
select throws_ok($$select internal.parent_conversation_command('moderate',(select message from conversations_fixture),'{"action":"HIDE","expectedVersion":0,"reason":"No report scope","confirmModeration":true}','conversation-admin-unreported',repeat('a',64),'conversation-test')$$,'42501',null,'administrator cannot moderate unreported private message');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.parent_conversation_list('threads',null,'{"limit":100}')$$,'42501',null,'student cannot enumerate parent teacher conversations');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')$$,'42501',null,'peer student cannot read adult thread');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.parent_conversation_command('read',(select message from conversations_fixture),'{}','conversation-recipient-read',repeat('e',64),'conversation-test')$$,'exact assigned teacher confirms recipient read');
update conversations_fixture set reply=(internal.parent_conversation_command('send',id,'{"body":"Check the example with your child. Teacher interpretation only."}','conversation-reply',repeat('f',64),'conversation-test')->>'id')::uuid;
select lives_ok($$select internal.parent_conversation_command('send',(select id from conversations_fixture),'{"body":"Check the example with your child. Teacher interpretation only."}','conversation-reply',repeat('f',64),'conversation-test')$$,'original message key returns same committed message');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select m->>'recipientReadAt'from jsonb_array_elements(internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')->'items')m where m->>'id'=(select reply::text from conversations_fixture)),null,'reply remains unread until exact recipient action');
select internal.parent_conversation_command('report',(select reply from conversations_fixture),'{"reason":"Parent asks school to review wording"}','conversation-report',repeat('a',64),'conversation-test')is not null as reported;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')->'items'),1,'administrator message view is bounded to exact reported content');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.parent_conversation_command('moderate',(select reply from conversations_fixture),'{"action":"HIDE","expectedVersion":0,"reason":"Teacher hides reported wording","confirmModeration":true}','conversation-hide',repeat('b',64),'conversation-test')is not null as hidden;
select internal.parent_conversation_command('state',(select id from conversations_fixture),'{"state":"PAUSED","expectedVersion":0,"reason":"School pauses the exchange for review","confirmModeration":true}','conversation-pause',repeat('c',64),'conversation-test')is not null as paused;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(exists(select 1 from jsonb_array_elements(internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')->'items')m where m->>'id'=(select reply::text from conversations_fixture)and m->'body'='null'::jsonb and m->>'status'='HIDDEN'),'hidden source retains metadata without disclosed body');
select throws_ok($$select internal.parent_conversation_command('send',(select id from conversations_fixture),'{"body":"Cannot send while paused"}','conversation-paused-send',repeat('d',64),'conversation-test')$$,'42501',null,'paused thread blocks new participant messages');
reset role;update app.parent_relationships set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and parent_actor_id='20000000-0000-4000-8000-000000000072'and student_actor_id='20000000-0000-4000-8000-000000000012';set local role cuevo_api;
select throws_ok($$select internal.parent_conversation_list('messages',(select id from conversations_fixture),'{"limit":100}')$$,'42501',null,'revoked guardian removes future thread read');
select throws_ok($$select internal.parent_conversation_command('create',null,'{"learnerId":"20000000-0000-4000-8000-000000000012","parentId":"20000000-0000-4000-8000-000000000072","teacherId":"20000000-0000-4000-8000-000000000004","classId":"30000000-0000-4000-8000-000000000001","subjectId":"43000000-0000-4000-8000-000000000001","title":"Explain checking","body":"Please explain the next step"}','conversation-create',repeat('c',64),'conversation-test')$$,'42501',null,'original create replay cannot bypass current guardian revocation');
select ok(not has_table_privilege('authenticated','app.parent_conversation_messages','select'),'Data API message bytes have no grants');select ok(not has_table_privilege('cuevo_api','app.parent_conversations','select'),'API raw thread table grant remains denied');select ok(not has_function_privilege('cuevo_worker','internal.parent_conversation_list(text,uuid,jsonb)','execute'),'worker cannot read protected message context');
reset role;select is((select count(*)from app.parent_conversation_messages where conversation_id=(select id from conversations_fixture)),2::bigint,'message/replay preserve two immutable actual source messages');select*from finish();rollback;



